    rseps = [r for r in range(h) if all(v == sep for v in grid[r])]
    cseps = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    def spans(n, seps):
        bounds = [-1] + seps + [n]
        return [(a + 1, b) for a, b in zip(bounds, bounds[1:])]
    rs, cs = spans(h, rseps), spans(w, cseps)
    # Use the first panel containing non-background artwork as the repeating tile.
    source = None
    for ri, (r0, r1) in enumerate(rs):
        for ci, (c0, c1) in enumerate(cs):
            tile = [row[c0:c1] for row in grid[r0:r1]]
            if any(v != bg for row in tile for v in row):
                source = tile
                break
        if source is not None:
            break
    if source is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r0, r1 in rs:
        for c0, c1 in cs:
            for i in range(r1-r0):
                for j in range(c1-c0):
                    out[r0+i][c0+j] = source[i % len(source)][j % len(source[0])]
    return out
